// Generates site/rts/js/sim/tabelas.js: integer trigonometry for the deterministic simulation.
// Floats are allowed here, offline; the generated file holds only integer literals, so every engine reads the same
// numbers. Run after changing a constant below and commit the output:
//   node ferramentas/rts/tabelas/gerar-tabelas.mjs
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const VOLTA = 256; // angle units per full turn
const ESCALA = 1024; // sine and cosine are scaled by one cell in world units
const PASSOS_TANGENTE = 256; // resolution of the first-octant arctangent table

const seno = Array.from({ length: VOLTA }, (_, k) => Math.round(Math.sin((2 * Math.PI * k) / VOLTA) * ESCALA));
// arctangent of i / PASSOS_TANGENTE for i in 0..PASSOS_TANGENTE, in angle units (0..VOLTA/8)
const arcoTangente = Array.from({ length: PASSOS_TANGENTE + 1 }, (_, i) => Math.round((Math.atan(i / PASSOS_TANGENTE) * VOLTA) / (2 * Math.PI)));

const linhas = (lista, porLinha) => {
  const saida = [];
  for (let i = 0; i < lista.length; i += porLinha) saida.push(`  ${lista.slice(i, i + porLinha).join(', ')},`);
  return saida.join('\n');
};

const fonte = `// Generated by ferramentas/rts/tabelas/gerar-tabelas.mjs; do not edit by hand.
// Integer trigonometry for the simulation: no Math.sin, Math.cos or Math.atan2, which engines may round differently.

export const ESCALA_SENO = ${ESCALA};
export const PASSOS_TANGENTE = ${PASSOS_TANGENTE};

/** sin(2 pi k / 256) * ESCALA_SENO, rounded, for k in 0..255. */
export const SENO = Int16Array.from([
${linhas(seno, 16)}
]);

/** atan(i / PASSOS_TANGENTE) in angle units (a full turn is 256), rounded, for i in 0..PASSOS_TANGENTE. */
export const ARCO_TANGENTE = Uint8Array.from([
${linhas(arcoTangente, 32)}
]);
`;

const destino = fileURLToPath(new URL('../../../site/rts/js/sim/tabelas.js', import.meta.url));
writeFileSync(destino, fonte);
console.log(`gravado ${destino}`);
